from __future__ import annotations

from typing import Callable

from shopkit.api.webhook_delivery import ALWAYS_DELIVER


def explain_delay(event: str, order_id: str | None, under_review: Callable[[str], bool] | None) -> str | None:
    """Return a short reason (any non-empty string) when our webhook worker would hold
    that event back right now, and None when it would send it normally."""
    if not order_id:
        return None
    if event in ALWAYS_DELIVER:
        return None
    if under_review is not None:
        try:
            if bool(under_review(order_id)):
                return "order in review"
        except Exception:
            return "order in review"
    return None
